1  #include "leptfuzz.h"
     2
     3  extern "C" int
     4  LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
     5  {
     6      BOX *box;
     7      PIX *pixs, *pixd;
     8      PIX *pix1, *pix2, *pix3, *pix4, *pix5, *pix6, *pix7, *pix8;
     9      PIXCMAP *cmap;
    10
    11      leptSetStdNullHandler();
    12      pixs = pixReadMemSpix(data, size);
    13      if(pixs==NULL) return 0;
    14
    15      pix1 = pixThresholdTo4bpp(pixs, 6, 1);
    16      box = boxCreate(120, 30, 200, 200);
    17      pixColorGray(pix1, box, L_PAINT_DARK, 220, 0, 0, 255);
    18      boxDestroy(&box);
    19
    20      pix2 = pixScale(pix1, 1.5, 1.5);
    21
    22      cmap = pixGetColormap(pix1);
    23      pix3 = pixOctcubeQuantFromCmap(pix2, cmap, 4,
    24                                     3, L_EUCLIDEAN_DISTANCE);
    25
    26      pix4 = pixConvertTo32(pix3);
    27      pix5 = pixMedianCutQuant(pix4, 0);
    28      pix6 = pixFewColorsMedianCutQuantMixed(pix4, 30, 30, 100, 0, 0, 0);
    29
    30      pixd = pixDeskew(pixs, 0);
    31      pixWriteImpliedFormat("/tmp/lept/deskew/result1", pixd, 0, 0);
    32
    33      pixOctreeQuantByPopulation(pixs, 0, 0);
    34      pix7 = pixFewColorsOctcubeQuantMixed(pix4, 3, 20, 244, 20, 0.05, 15);
    35      pix8 = pixColorSegment(pixs, 50, 6, 6, 6, 0);
    36
    37      pixDestroy(&pix1);
    38      pixDestroy(&pix2);
    39      pixDestroy(&pix3);
    40      pixDestroy(&pix4);
    41      pixDestroy(&pix5);
    42      pixDestroy(&pix6);
    43      pixDestroy(&pix7);
    44      pixDestroy(&pix8);
    45
    46      pixDestroy(&pixd);
    47      pixDestroy(&pixs);
    48      pixcmapDestroy(&cmap);
    49
    50      return 0;
    51  }
